Rules.InvariantScript:
If(
    tgMostraApontamentos.Checked,

    // Exibe apenas os apontamentos com erro
    With(
        {
            blocoFiltro: Text(cmbCLGbloco.Selected.Value),
            aeroportoFiltro: Text(cmbCLGaeroporto.Selected.Result)
        },
        FirstN(

                Filter(
                    Sort(
                    tbl_Checklist_generico_base, ID , SortOrder.Descending) As Base,
                    (IsBlank(blocoFiltro) || StartsWith(Base.Bloco, blocoFiltro)) &&
                    (IsBlank(aeroportoFiltro) || StartsWith(Base.Aeroporto, aeroportoFiltro)) &&
                    !IsBlank(
                        LookUp(
                            Filter(tbl_Checklist_generico_objeto, ID_checkList = Base.ID),
                            Resposta = "Não conforme" And Status <> "Normalizado"
                        )
                    )
                ),

            Value(txtLimit_5.Text)
        )
    ),

    // Exibe todos com filtros opcional de empresa
    With(
        {
            blocoFiltro: Text(cmbCLGbloco.Selected.Value),
            aeroportoFiltro: Text(cmbCLGaeroporto.Selected.Result),
            empresaBusca: txtBuscarInspPatio_4.Text
        },
        FirstN(
            SortByColumns(
                Filter(
                    AddColumns(
                        Sort(
                        tbl_Checklist_generico_base,ID,SortOrder.Descending),
                        EmpresaNome,
                        With(
                            {
                                veic: First(
                                    SortByColumns(
                                        Filter(Sort( tbl_Veiculos_equipamentos,ID, SortOrder.Descending), ID = ID_FK),
                                        "ID",
                                        SortOrder.Descending
                                    )
                                )
                            },
                            If(!IsBlank(veic), veic.Empresa, "")
                        )
                    ),
                    (IsBlank(blocoFiltro) || StartsWith(Bloco, blocoFiltro)) &&
                    (IsBlank(aeroportoFiltro) || StartsWith(Aeroporto, aeroportoFiltro)) &&
                    (IsBlank(empresaBusca) || StartsWith(EmpresaNome, empresaBusca))
                ),
                "ID",
                SortOrder.Descending
            ),
            Value(txtLimit_5.Text)
        )
    )
)


